  id: string;
  title: string;
};

const projectCache = new Map<string, CachedProject>();

export async function getCachedProject(
  id: string,
  load: () => Promise<CachedProject>,
) {
  const cached = projectCache.get(id);
  if (cached) return cached;
  const project = await load();
  projectCache.set(id, project);
  return project;
}

export function clearProjectCache() {
  projectCache.clear();
}
","truncated":false}}

{"status":"ok","receipt":"r7","data":{"path":"src/project-reducer.ts","view":"raw","complete":true,"editTargets":[{"alias":"s11","qualifiedName":"ProjectSaveState"},{"alias":"s12","qualifiedName":"ProjectSaveAction"},{"alias":"s13","qualifiedName":"projectSaveReducer"}],"content":"export type ProjectSaveState = {
  activeRequestId?: string;
  error?: string;
  savedTitle: string;
  status: "error" | "idle" | "saving";
  title: string;
};

export type ProjectSaveAction =
  | { requestId: string; type: "save_started" }
  | { requestId: string; type: "save_succeeded" }
  | { message: string; requestId: string; type: "save_failed" };

export function projectSaveReducer(
  state: ProjectSaveState,
  action: ProjectSaveAction,
): ProjectSaveState {
  if (action.type === "save_started")
    return { ...state, activeRequestId: action.requestId, status: "saving" };
  if (action.type === "save_succeeded")
    return { ...state, savedTitle: state.title, status: "idle" };
  return { ...state, error: action.message, status: "error" };
}
","truncated":false}}

