export function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  let inspected = decoded;
  while (true) {
    const inspectedPath = inspected.replaceAll("\\", "/");
    if (
      inspectedPath.startsWith("/") ||
      /^[A-Za-z]:\//.test(inspectedPath) ||
      inspectedPath.split("/").some((segment) => segment === "..")
    ) {
      return null;
    }

    let next: string;
    try {
      next = decodeURIComponent(inspected);
    } catch {
      break;
    }

    if (next === inspected) {
      break;
    }
    inspected = next;
  }

  const path = decoded.replaceAll("\\", "/");
  const normalized = path
    .split("/")
    .filter((segment) => segment && segment !== ".")
    .join("/");

  return normalized || null;
}

