export function slugifyProject(project: { id: string; title: string }) {
  const slug = project.title
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

  return slug || `project-${project.id}`;
}

export function projectUrl(project: ProjectLink) {
  return `/projects/${slugifyProject(project)}`;
}

