export function parseCsvRow(row: string) {
  const values: string[] = [];
  let value = "";
  let quoted = false;

  for (let index = 0; index <= row.length; index += 1) {
    const character = row[index];

    if (quoted) {
      if (character === '"') {
        if (row[index + 1] === '"') {
          value += '"';
          index += 1;
        } else {
          quoted = false;
        }
      } else {
        value += character;
      }
    } else if (character === '"' && value.length === 0) {
      quoted = true;
    } else if (character === "," || index === row.length) {
      values.push(value.trim());
      value = "";
    } else {
      value += character;
    }
  }

  return values;
}

