const execution = Promise.resolve().then(handle);
processingWebhookIds.set(eventId, execution);

try {
  await execution;
  if (stateVersion === webhookStateVersion) {
    processedWebhookIds.add(eventId);
  }
  return true;
} finally {
  if (processingWebhookIds.get(eventId) === execution) {
