const fields: string[] = [];
let field = "";
let inQuotes = false;
let quotedField = false;
let afterClosingQuote = false;

const pushField = () => {
  fields.push(quotedField ? field : field.trim());
  field = "";
  quotedField = false;
  afterClosingQuote = false;
};

for (let index = 0; index < row.length; index += 1) {
  const character = row[index];

  if (inQuotes) {
    if (character === '"') {
      if (row[index + 1] === '"') {
        field += '"';
        index += 1;
      } else {
        inQuotes = false;
        afterClosingQuote = true;
      }
    } else {
      field += character;
    }
    continue;
  }

  if (afterClosingQuote) {
    if (character === ",") {
      pushField();
    }
    continue;
  }

  if (character === '"' && field.trim() === "") {
    field = "";
    inQuotes = true;
    quotedField = true;
  } else if (character === ",") {
    pushField();
  } else {
    field += character;
  }
}

pushField();
return fields;

